import json,collections
sets={
 "ClaudiniteWebsite#494":["mcp-github-pull_request_read-1789144650432.txt","mcp-github-pull_request_read-1789146322062.txt"],
 "EdFringeNow#670":["mcp-github-pull_request_read-1789144652156.txt","mcp-github-pull_request_read-1789146321748.txt"],
}
for label,files in sets.items():
    allf=[]
    for f in files:
        d=json.load(open(f))
        allf += d['files'] if isinstance(d,dict) and 'files' in d else d
    seen={}
    for it in allf: seen[it['filename']]=it
    allf=list(seen.values())
    print("=== %s : %d unique files ===" % (label,len(allf)))
    agg=collections.Counter(); adds=collections.Counter(); dels=collections.Counter()
    for it in allf:
        p=it['filename']; parts=p.split('/')
        if p.startswith('.claudinite/shared/packs'): key='/'.join(parts[:4])
        elif p.startswith('.claudinite/shared'): key='.claudinite/shared/engine (+top-level)'
        elif p.startswith('.claudinite/local'): key='/'.join(parts[:4])
        else: key=p
        agg[key]+=1; adds[key]+=it.get('additions',0); dels[key]+=it.get('deletions',0)
    for k,v in agg.most_common():
        print("  %-58s %3d files  +%-5d -%-5d" % (k,v,adds[k],dels[k]))
    print()
EOF

